import React, { useState, useEffect, useCallback } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import styled from "styled-components";

const EmployeePage = () => {
  const { id } = useParams();
  const [employeeName, setEmployeeName] = useState("");
  const [employeePhone, setEmployeePhone] = useState("");
  const [employeeRole, setEmployeeRole] = useState("driver");
  const [employeeSalary, setEmployeeSalary] = useState("");
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [isFormVisible, setFormVisible] = useState(false);
  const [isUpdateFormVisible, setUpdateFormVisible] = useState(false);
  const [selectedEmployeeDetails, setSelectedEmployeeDetails] = useState(null);
  const [updatePhone, setUpdatePhone] = useState("");
  const [updateStartDate, setUpdateStartDate] = useState("");
  const [updateEndDate, setUpdateEndDate] = useState("");
  const [expensePaid, setExpensePaid] = useState("");

  const fetchEmployeesByRole = useCallback(
    async (role) => {
      try {
        const response = await axios.get(
          `http://localhost:5001/api/employee/employeesByRole/${id}/${role}`
        );
        setFilteredEmployees(response.data);
      } catch (error) {
        console.error("Error fetching employees:", error);
      }
    },
    [id]
  );

  const handleEmployeeClick = async (phone) => {
    try {
      const response = await axios.get(
        `http://localhost:5001/api/employee/${phone}`
      );
      setSelectedEmployeeDetails(response.data);
    } catch (error) {
      console.error("Error fetching employee details:", error);
      alert("Error fetching employee details");
    }
  };

  const addEmployee = async () => {
    try {
      const newEmployee = {
        name: employeeName,
        phone: employeePhone,
        role: employeeRole,
        salary: employeeSalary,
      };
      await axios.post(`http://localhost:5001/api/employee/add/${id}`, newEmployee);
      alert("Employee added successfully!");
      fetchEmployeesByRole(employeeRole); // Refresh the list
      setFormVisible(false);
    } catch (error) {
      console.error("Error adding employee:", error);
      alert("Failed to add employee.");
    }
  };

  const handleUpdateEmployee = async () => {
    try {
      const updateData = {
        phone: updatePhone,
        startDate: updateStartDate,
        endDate: updateEndDate,
        expense: expensePaid,
      };

      await axios.put(`http://localhost:5001/api/employee/updateExpense`, updateData);
      alert("Employee expense updated successfully!");
      fetchEmployeesByRole(employeeRole); // Refresh the list
      setUpdateFormVisible(false);
    } catch (error) {
      console.error("Error updating employee:", error);
      alert("Failed to update employee.");
    }
  };

  const deleteEmployee = async (phone) => {
    try {
      await axios.delete(`http://localhost:5001/api/employee/delete/${phone}`);
      alert("Employee deleted successfully!");
      fetchEmployeesByRole(employeeRole); // Refresh the list
    } catch (error) {
      console.error("Error deleting employee:", error);
      alert("Failed to delete employee.");
    }
  };

  useEffect(() => {
    fetchEmployeesByRole(employeeRole);
  }, [employeeRole, id, fetchEmployeesByRole]);

  return (
    <Container>
      <Header>
        <LorryTitle>Lorry {id}</LorryTitle>
      </Header>

      <Button onClick={() => setFormVisible(true)}>Add Employee</Button>

      {isFormVisible && (
        <Form>
          <Input
            type="text"
            placeholder="Employee Name"
            value={employeeName}
            onChange={(e) => setEmployeeName(e.target.value)}
          />
          <Input
            type="text"
            placeholder="Phone Number"
            value={employeePhone}
            onChange={(e) => setEmployeePhone(e.target.value)}
          />
          <Select
            value={employeeRole}
            onChange={(e) => setEmployeeRole(e.target.value)}
          >
            <option value="driver">Driver</option>
            <option value="driller">Driller</option>
            <option value="manager">Manager</option>
            <option value="worker">Worker</option>
          </Select>
          <Input
            type="number"
            placeholder="Fixed Salary"
            value={employeeSalary}
            onChange={(e) => setEmployeeSalary(e.target.value)}
          />
          <Button onClick={addEmployee}>Add Employee</Button>
          <Button onClick={() => setFormVisible(false)}>Cancel</Button>
        </Form>
      )}

      {isUpdateFormVisible && (
        <UpdateForm>
          <Input
            type="text"
            placeholder="Phone Number"
            value={updatePhone}
            onChange={(e) => setUpdatePhone(e.target.value)}
          />
          <Input
            type="date"
            placeholder="Start Date"
            value={updateStartDate}
            onChange={(e) => setUpdateStartDate(e.target.value)}
          />
          <Input
            type="date"
            placeholder="End Date"
            value={updateEndDate}
            onChange={(e) => setUpdateEndDate(e.target.value)}
          />
          <Input
            type="number"
            placeholder="Expense Paid"
            value={expensePaid}
            onChange={(e) => setExpensePaid(e.target.value)}
          />
          <Button onClick={handleUpdateEmployee}>Update Expense</Button>
          <Button onClick={() => setUpdateFormVisible(false)}>Cancel</Button>
        </UpdateForm>
      )}

      <RoleTabs>
        {["driver", "driller", "manager", "worker"].map((role) => (
          <Tab
            key={role}
            onClick={() => setEmployeeRole(role)}
            active={employeeRole === role}
          >
            {role.charAt(0).toUpperCase() + role.slice(1)}
          </Tab>
        ))}
      </RoleTabs>

      <EmployeeList>
        {filteredEmployees.map((employee) => (
          <EmployeeItem key={employee.phone}>
            <div onClick={() => handleEmployeeClick(employee.phone)}>
              {employee.name} ({employee.phone})
            </div>
            <Button onClick={() => {
              setUpdatePhone(employee.phone);
              setUpdateFormVisible(true);
            }}>
              Update
            </Button>
            <Button onClick={() => deleteEmployee(employee.phone)}>Delete</Button>
            <Button onClick={() => handleEmployeeClick(employee.phone)}>
              Details
            </Button>
          </EmployeeItem>
        ))}
      </EmployeeList>

      {selectedEmployeeDetails && (
        <DetailsTable>
          <thead>
            <tr>
              <th>Name</th>
              <th>Phone</th>
              <th>Start Date</th>
              <th>End Date</th>
              <th>Expense</th>
            </tr>
          </thead>
          <tbody>
            {selectedEmployeeDetails.salaryRecords.map((record, index) => (
              <tr key={index}>
                <td>{selectedEmployeeDetails.name}</td>
                <td>{selectedEmployeeDetails.phone}</td>
                <td>{record.startDate}</td>
                <td>{record.endDate}</td>
                <td>{record.expense}</td>
              </tr>
            ))}
          </tbody>
        </DetailsTable>
      )}
    </Container>
  );
};

export default EmployeePage;

// Styled Components
const Container = styled.div`
  padding: 20px;
  background-color: #f4f7fc;
`;

const Header = styled.header`
  display: flex;
  justify-content: center;
  padding: 20px;
  background-color: #ffffff;
